import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Eingabeblöcke","description":"Formularfeld-Blöcke auf Seiten konfigurieren.","frontmatter":{"title":"Eingabeblöcke","description":"Formularfeld-Blöcke auf Seiten konfigurieren."},"headers":[],"relativePath":"seiten/eingabebloecke.md","filePath":"seiten/eingabebloecke.md","lastUpdated":1786174778000}'),a={name:"seiten/eingabebloecke.md"};function s(d,e,l,o,h,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="eingabeblocke" tabindex="-1">Eingabeblöcke <a class="header-anchor" href="#eingabeblocke" aria-label="Permalink to &quot;Eingabeblöcke&quot;">​</a></h1><p>Seiten kennen dieselben Eingabefelder wie <a href="/docs/formulare/felder-konfigurieren">Formulare</a> — hier aber frei platzierbar, kombinierbar mit Text und Layout und mit <a href="/docs/seiten/sichtbarkeit">bedingter Sichtbarkeit</a>.</p><h2 id="gemeinsame-einstellungen" tabindex="-1">Gemeinsame Einstellungen <a class="header-anchor" href="#gemeinsame-einstellungen" aria-label="Permalink to &quot;Gemeinsame Einstellungen&quot;">​</a></h2><p>Jeder Eingabeblock hat unter <strong>Feld Einstellungen</strong>:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Pflichtfeld</strong></td><td>Ohne Eingabe kein Absenden. Fehler: <em>Dieses Feld ist ein Pflichtfeld</em></td></tr><tr><td><strong>Nicht änderbar</strong></td><td>Wird angezeigt, lässt sich aber nicht bearbeiten</td></tr><tr><td><strong>Farbe</strong></td><td>Farbliche Gestaltung des Feldes</td></tr><tr><td><strong>Key</strong></td><td>Technischer Bezeichner des Feldes</td></tr></tbody></table><h3 id="der-key" tabindex="-1">Der Key <a class="header-anchor" href="#der-key" aria-label="Permalink to &quot;Der Key&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Der Key ist das Bindeglied zu Flows und Sichtbarkeit</p><p>Die Oberfläche erklärt ihn so: <em>Wird verwendet, um dieses Feld in Workflows und Formularwerten zu referenzieren.</em></p><p>Konkret brauchen Sie ihn an zwei Stellen:</p><ul><li>in der <a href="/docs/seiten/sichtbarkeit">bedingten Sichtbarkeit</a>, etwa <code>formValues.get(&#39;alter&#39;)</code></li><li>in <a href="/docs/flows/daten-zwischen-schritten">Flows</a>, wenn die Seite Daten an einen Ablauf übergibt</li></ul><p>Vergeben Sie sprechende Keys wie <code>alter</code> oder <code>abteilung</code>, bevor Sie damit arbeiten — nachträgliche Änderungen brechen bestehende Bedingungen.</p></div><p>Über <strong>Keys verwalten</strong> sehen Sie alle Keys einer Seite auf einmal.</p><hr><h2 id="textfelder" tabindex="-1">Textfelder <a class="header-anchor" href="#textfelder" aria-label="Permalink to &quot;Textfelder&quot;">​</a></h2><p><strong>Einzeiliges</strong> und <strong>Mehrzeiliges Textfeld</strong> unterstützen dieselben <a href="/docs/grids/eintraege#emoticon-kurzbefehle">Emoticon-Kurzbefehle</a> wie Grid-Textzellen: <code>(/)</code> wird zu ✅, <code>(x)</code> zu ❌, <code>(Y)</code> zu 👍 und so weiter.</p><hr><h2 id="bewertungsskala" tabindex="-1">Bewertungsskala <a class="header-anchor" href="#bewertungsskala" aria-label="Permalink to &quot;Bewertungsskala&quot;">​</a></h2><p>Erfasst Bewertungen als Zahl, mit fünf möglichen Darstellungen.</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Auswahl</th></tr></thead><tbody><tr><td><strong>Stil</strong></td><td><em>Empfehlungsskala (NPS)</em>, <em>Segmentiert</em>, <em>Sterne</em>, <em>Emoji</em>, <em>Slider</em></td></tr><tr><td><strong>Minimum</strong> / <strong>Maximum</strong></td><td>Wertebereich</td></tr><tr><td><strong>Schritt</strong></td><td>Abstand zwischen den Werten</td></tr><tr><td><strong>Minimum-Beschriftung</strong> / <strong>Maximum-Beschriftung</strong></td><td>Text an den Enden</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Stil nach Zweck wählen</p><ul><li><strong>Sterne</strong> — vertraut für Produkt- und Servicebewertungen</li><li><strong>Emoji</strong> — niedrigschwellig, gut für kurze Rückmeldungen</li><li><strong>Empfehlungsskala (NPS)</strong> — der etablierte 0-bis-10-Aufbau für Weiterempfehlungsfragen</li><li><strong>Segmentiert</strong> — neutral, gut mit Beschriftungen an den Enden</li><li><strong>Slider</strong> — für größere Wertebereiche</li></ul><p>Die Endbeschriftungen lohnen sich fast immer: „trifft gar nicht zu&quot; bis „trifft voll zu&quot; macht aus abstrakten Zahlen eine verständliche Frage.</p></div><p>Fehlt eine Eingabe: <em>Bitte wählen Sie einen Wert</em>.</p><hr><h2 id="hakchen" tabindex="-1">Häkchen <a class="header-anchor" href="#hakchen" aria-label="Permalink to &quot;Häkchen&quot;">​</a></h2><p>Zusätzlich zu den gemeinsamen Einstellungen:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Muss aktiviert sein</strong></td><td>Das Häkchen muss gesetzt werden</td></tr><tr><td><strong>Farbe</strong></td><td>Darstellung</td></tr></tbody></table><p>Fehler: <em>Dieses Feld muss aktiviert sein</em> beziehungsweise <em>{Beschriftung} muss aktiviert sein</em>.</p><div class="tip custom-block"><p class="custom-block-title">Für Einwilligungen</p><p><em>Muss aktiviert sein</em> ist der Unterschied zu einem gewöhnlichen Pflichtfeld: Ein Häkchen als Pflichtfeld wäre auch mit „nicht gesetzt&quot; erfüllt. Für Zustimmungen zu Bedingungen oder Datenschutzhinweisen brauchen Sie diese Einstellung.</p></div><hr><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Zeigt eine Ja/Nein-Auswahl als Karten und speichert sie als Wahrheitswert.</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Beschriftung Ja</strong></td><td>Text der Zustimmungs-Karte</td></tr><tr><td><strong>Beschriftung Nein</strong></td><td>Text der Ablehnungs-Karte</td></tr></tbody></table><p>Fehler: <em>Bitte treffen Sie eine Auswahl</em>.</p><div class="tip custom-block"><p class="custom-block-title">Deutlicher als ein Häkchen</p><p>Bei bewussten Entscheidungen — „Teilnahme zusagen&quot; / „Absagen&quot; — ist dieser Block klarer als ein Häkchen, weil beide Möglichkeiten sichtbar sind und keine voreingestellt ist.</p></div><hr><h2 id="dateien-oder-fotos-hochladen" tabindex="-1">Dateien oder Fotos hochladen <a class="header-anchor" href="#dateien-oder-fotos-hochladen" aria-label="Permalink to &quot;Dateien oder Fotos hochladen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Maximale Anzahl von Dateien</strong></td><td><em>Leer lassen für unbegrenzt</em></td></tr><tr><td><strong>Upload eingeschränkt auf Dateien vom Typ</strong></td><td>Beschränkt die erlaubten Typen</td></tr><tr><td><strong>Erlaubte Dateitypen</strong></td><td><em>Alle</em>, <em>PDF</em>, <em>Bild</em>, <em>PNG</em>, <em>JPEG</em>, <em>CSV</em></td></tr><tr><td><strong>Nur Hinzufügen von Dateien erlauben</strong></td><td>Bestehende Anhänge nicht löschbar</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Typen einschränken spart Rückfragen</p><p>Wenn Sie ein PDF brauchen, stellen Sie den Typ auf <em>PDF</em>. Sonst kommen Fotos vom Bildschirm, Word-Dateien und Screenshots.</p><p>Die maximale Dateigröße ist tarifabhängig und lässt sich hier nicht ändern.</p></div><hr><h2 id="aufnahme-blocke" tabindex="-1">Aufnahme-Blöcke <a class="header-anchor" href="#aufnahme-blocke" aria-label="Permalink to &quot;Aufnahme-Blöcke&quot;">​</a></h2><p><strong>Sprachaufnahme</strong>, <strong>Video hochladen</strong> und <strong>Foto Kamera</strong> nehmen direkt über das Gerät auf.</p><p>Bei Video und Foto lässt sich über <strong>Anweisung bearbeiten</strong> ein Hinweistext hinterlegen, der beim Aufnehmen erscheint. Beim Foto zusätzlich <strong>Zeitstempel hinzufügen</strong> und <strong>Button-Farbe</strong>.</p><p>Bedienelemente: <em>START</em>, <em>PAUSE</em>, <em>WEITER</em>, <em>Fertig</em>. Ohne Berechtigung: <em>Bitte erlauben Sie den Zugriff auf das Mikrofon</em>.</p><div class="tip custom-block"><p class="custom-block-title">Zeitstempel bei Dokumentation</p><p>Für Baustellen-, Schadens- und Wartungsdokumentation ist <em>Zeitstempel hinzufügen</em> nützlich — das Aufnahmedatum steht dann im Bild selbst.</p></div><hr><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2><p>Der Video-Block kann verpflichtend gemacht werden:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Bis zum Ende anschauen</strong></td><td>Weiterkommen erst nach vollständigem Ansehen</td></tr></tbody></table><p>Hinweis für Besucher: <em>Bitte schauen Sie das Video bis zum Ende an.</em></p><div class="tip custom-block"><p class="custom-block-title">Für Unterweisungen</p><p>In Kombination mit dem <a href="/docs/seiten/layout-bloecke">Stepper-Layout</a> und einem Häkchen <em>Muss aktiviert sein</em> lässt sich damit eine einfache Unterweisung abbilden: Video ansehen, Kenntnisnahme bestätigen, absenden.</p></div><hr><h2 id="barcode-scanner" tabindex="-1">Barcode-Scanner <a class="header-anchor" href="#barcode-scanner" aria-label="Permalink to &quot;Barcode-Scanner&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Textfeld anzeigen</strong></td><td>Erlaubt zusätzlich manuelle Eingabe</td></tr><tr><td><strong>Button-Farbe</strong></td><td>Darstellung</td></tr></tbody></table><p>Platzhalter: <em>Code manuell eingeben oder scannen</em>. Ohne Wert: <em>Kein Wert gescannt</em>.</p><p>Fehlermeldungen zur Kamera:</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Ursache</th></tr></thead><tbody><tr><td><em>Kameraberechtigung verweigert. Bitte erlauben Sie den Kamerazugriff in Ihren Browsereinstellungen.</em></td><td>Zugriff abgelehnt</td></tr><tr><td><em>Keine Kamera gefunden. Bitte verbinden Sie eine Kamera mit Ihrem Gerät.</em></td><td>Kein Gerät</td></tr><tr><td><em>Kamera wird bereits von einer anderen Anwendung verwendet.</em></td><td>Belegt</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Textfeld immer aktiv lassen</p><p>Kameras schlagen fehl: schlechtes Licht, beschädigter Code, fehlende Berechtigung. Mit <em>Textfeld anzeigen</em> kann die Person die Nummer notfalls abtippen, statt den Vorgang abzubrechen.</p></div><hr><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/referenz/blocktypen">Blocktypen-Referenz</a></li><li><a href="/docs/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a></li><li><a href="/docs/seiten/layout-bloecke">Layout-Blöcke</a></li></ul>',55)])])}const m=t(a,[["render",s]]);export{g as __pageData,m as default};
